L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "\227\129\163\227\129\159\227\129\143\227\128\129\227\130\180\227\131\159\227\130\146\227\129\130\227\129\149\227\129\163\227\129\166\231\148\159\227\129\141\227\129\166\227\130\139\227\129\168\227\129\147\227\130\141\227\130\146\233\157\162\229\128\146\232\166\139\227\129\166\227\130\132\227\129\163\227\129\159\227\129\174\227\129\171\227\128\129\230\129\169\231\159\165\227\130\137\227\129\154\227\129\160\227\129\170\227\128\130"
L33_1.m_Talk_JPN = L34_1
L34_1 = "You ungrateful little thing. We fed you and gave you a place to sleep when you could've spent your entire life on the street."
