L33_1.m_Talk_TWN = L34_1
L34_1 = "\224\184\162\224\184\177\224\184\162\224\185\128\224\184\148\224\185\135\224\184\129\224\185\132\224\184\161\224\185\136\224\184\163\224\184\185\224\185\137\224\184\136\224\184\177\224\184\129\224\184\154\224\184\184\224\184\141\224\184\132\224\184\184\224\184\147\224\184\132\224\184\153 \224\185\128\224\184\163\224\184\178\224\185\131\224\184\171\224\185\137\224\184\173\224\184\178\224\184\171\224\184\178\224\184\163\224\185\129\224\184\165\224\184\176\224\185\131\224\184\171\224\185\137\224\184\151\224\184\181\224\185\136\224\184\153\224\184\173\224\184\153 \224\184\151\224\184\177\224\185\137\224\184\135\224\184\151\224\184\181\224\185\136\224\185\129\224\184\129\224\184\173\224\184\178\224\184\136\224\184\149\224\185\137\224\184\173\224\184\135\224\184\173\224\184\162\224\184\185\224\185\136\224\184\130\224\185\137\224\184\178\224\184\135\224\184\150\224\184\153\224\184\153\224\184\149\224\184\165\224\184\173\224\184\148\224\184\138\224\184\181\224\184\167\224\184\180\224\184\149"
L33_1.m_Talk_THA = L34_1
L34_1 = "T\195\170n nh\195\179c con v\195\180 \198\161n. B\225\187\141n tao \196\145\195\163 cho m\195\160y \196\145\225\187\147 \196\131n v\195\160 ch\225\187\151 ng\225\187\167 trong khi m\195\160y c\195\179 th\225\187\131 s\225\186\189 ph\225\186\163i d\195\160nh c\225\186\163 \196\145\225\187\157i v\225\186\165t v\198\176\225\187\159ng tr\195\170n \196\145\198\176\225\187\157ng ph\225\187\145."
L33_1.m_Talk_VTN = L34_1
L34_1 = "\231\156\159\230\152\175\231\154\132\239\188\140\231\187\153\228\189\160\232\191\153\228\185\158\228\184\144\229\144\131\231\154\132\231\169\191\231\154\132\239\188\140\229\136\176\229\164\180\230\157\165\232\191\152\228\184\141\230\135\130\229\190\151\230\138\165\230\129\169\227\128\130"
